import{_ as o,r as s,o as p,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"MultisiteGroup - October CMS - 4.x","titleTemplate":false,"description":"Learn how to scope model records to a site group for multi-tenancy.","frontmatter":{"subtitle":"Learn how to scope model records to a site group for multi-tenancy."},"headers":[{"level":2,"title":"Declaration","slug":"declaration","link":"#declaration","children":[]},{"level":2,"title":"How It Works","slug":"how-it-works","link":"#how-it-works","children":[]},{"level":2,"title":"Programmatic Toggling","slug":"programmatic-toggling","link":"#programmatic-toggling","children":[]},{"level":2,"title":"Custom Column Name","slug":"custom-column-name","link":"#custom-column-name","children":[]},{"level":2,"title":"Combining with Translatable","slug":"combining-with-translatable","link":"#combining-with-translatable","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/multisite/multisite-group.md","filePath":"4.x/extend/multisite/multisite-group.md"}'),r={name:"4.x/extend/multisite/multisite-group.md"};function u(d,a,k,h,g,m){const t=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"MultisiteGroup",-1)),n(e),a[1]||(a[1]=i(`<div class="custom-block aside"><p>For an overview of when to use this trait versus Multisite or Translatable, see the <a href="./introduction.html">Introduction</a>.</p></div><p>The MultisiteGroup trait scopes model records to a <a href="./../../cms/multisite/multisite.html">site group</a>, providing multi-tenancy support. Unlike the <a href="./multisite.html">Multisite</a> trait which creates duplicate rows per site, MultisiteGroup filters a single set of records by the active site group. Each site group typically represents a distinct website or tenant.</p><p>For example, a &quot;Dogs&quot; website and a &quot;Cats&quot; website might share the same October CMS installation but have completely separate product catalogs. MultisiteGroup ensures each tenant only sees its own data.</p><h2 id="declaration"><a href="#declaration" class="header-anchor">#</a> Declaration</h2><p>To scope a model by site group, apply the <code>October\\Rain\\Database\\Traits\\MultisiteGroup</code> trait.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>MultisiteGroup</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To add a <code>site_group_id</code> column to your table, use the <code>integer</code> method inside a migration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;products&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_group_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="how-it-works"><a href="#how-it-works" class="header-anchor">#</a> How It Works</h2><p>The trait registers a global scope that automatically filters queries by the active site group. When a model is saved, the <code>site_group_id</code> column is automatically set to the current site group from context.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Only returns products belonging to the active site group</span>
<span class="token variable">$products</span> <span class="token operator">=</span> <span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When the global context is active (via <code>Site::withGlobalContext</code>), the scope is bypassed and records from all site groups are accessible.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withGlobalContext</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Returns products from all site groups</span>
    <span class="token variable">$allProducts</span> <span class="token operator">=</span> <span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="programmatic-toggling"><a href="#programmatic-toggling" class="header-anchor">#</a> Programmatic Toggling</h2><p>The <code>isMultisiteGroupEnabled</code> method returns <code>true</code> by default. Override it to conditionally disable the global scope.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">isMultisiteGroupEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token keyword return-type">bool</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasSiteGroups</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="custom-column-name"><a href="#custom-column-name" class="header-anchor">#</a> Custom Column Name</h2><p>By default the trait uses <code>site_group_id</code> as the column name. You may customize this by defining the <code>SITE_GROUP_ID</code> constant on your model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">SITE_GROUP_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_group_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="combining-with-translatable"><a href="#combining-with-translatable" class="header-anchor">#</a> Combining with Translatable</h2><p>MultisiteGroup and <a href="./translatable.html">Translatable</a> work naturally together. The group scopes which records are visible, while Translatable handles per-attribute translations within the group&#39;s languages.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>MultisiteGroup</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Translatable</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$translatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;description&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In this configuration, each site group (tenant) has its own product catalog, and the product names and descriptions can be translated across the languages defined within that group.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./introduction.html">Introduction</a></li><li><a href="./multisite.html">Multisite Trait</a></li><li><a href="./translatable.html">Translatable Trait</a></li><li><a href="./../../cms/multisite/multisite.html">Site Groups</a></li><li><a href="./../services/site.html">Site Service</a></li></ul></div>`,25))])}const w=o(r,[["render",u]]);export{f as __pageData,w as default};
